package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.Zero
var WsWrapTotal decimal.Decimal = decimal.Zero
var WsSafeTotal decimal.Decimal = decimal.Zero
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.Zero
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var AmtRecData AmtRec
var amtFile *os.File
var amtScanner *bufio.Scanner
var InputDone bool = false

type PicInfo struct {
	IntDigits int
	Scale     int
}

var picBig = PicInfo{IntDigits: 7, Scale: 2}
var picWrap = PicInfo{IntDigits: 5, Scale: 2}
var picSafe = PicInfo{IntDigits: 5, Scale: 2}
var picHalfInfo = PicInfo{IntDigits: 5, Scale: 1}

func pow10(n int) int64 {
	if n <= 0 {
		return 1
	}
	// avoid math.Pow float errors
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	_ = math.Pow10 // keep import used
	return r
}

func isOverflow(v decimal.Decimal, pic PicInfo) bool {
	if v.IsNegative() {
		return true
	}
	limit := decimal.New(1, int32(pic.IntDigits))
	return v.GreaterThanOrEqual(limit)
}

func wrapDecimal(v decimal.Decimal, pic PicInfo) decimal.Decimal {
	vt := v.Truncate(int32(pic.Scale))
	scaled := vt.Shift(int32(pic.Scale)).Truncate(0)
	scaledInt := scaled.IntPart()
	mod := pow10(pic.IntDigits + pic.Scale)
	rem := scaledInt % mod
	if rem < 0 {
		rem += mod
	}
	return decimal.New(rem, -int32(pic.Scale))
}

func addWithWrap(target decimal.Decimal, amt decimal.Decimal, pic PicInfo) decimal.Decimal {
	tentative := target.Add(amt).Truncate(int32(pic.Scale))
	if isOverflow(tentative, pic) {
		return wrapDecimal(tentative, pic)
	}
	return tentative
}

func moveWithWrap(src decimal.Decimal, pic PicInfo) decimal.Decimal {
	srcTrunc := src.Truncate(int32(pic.Scale))
	if isOverflow(srcTrunc, pic) {
		return wrapDecimal(srcTrunc, pic)
	}
	return srcTrunc
}

func parseAmtField(s string) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.Zero
	}
	b := strings.Builder{}
	for _, r := range s {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		} else if r == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	digits := b.String()
	d, err := decimal.NewFromString(digits)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-2)
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		decPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	intCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intCount++
		}
	}
	decCount := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			decCount++
		}
	}
	vt := val.Truncate(int32(decCount))
	if vt.IsNegative() {
		vt = vt.Abs()
	}
	intPart := vt.Truncate(0)
	intStr := intPart.StringFixed(0)
	// StringFixed may return "0"
	if intStr == "" {
		intStr = "0"
	}
	// remove sign if any (we already abs)
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	if strings.HasPrefix(intStr, "+") {
		intStr = intStr[1:]
	}
	if len(intStr) > intCount {
		intStr = intStr[len(intStr)-intCount:]
	} else if len(intStr) < intCount {
		intStr = strings.Repeat("0", intCount-len(intStr)) + intStr
	}
	fracStr := ""
	if decCount > 0 {
		fracVal := vt.Sub(intPart)
		if fracVal.IsNegative() {
			fracVal = fracVal.Abs()
		}
		fracScaled := fracVal.Shift(int32(decCount)).Truncate(0)
		fracInt := fracScaled.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		fracStr = fmt.Sprintf("%0*d", decCount, fracInt)
	}
	digitSeq := intStr + fracStr
	// positions of digit placeholders in picture order
	digitPos := []int{}
	for i, ch := range picture {
		if ch == 'Z' || ch == '9' {
			digitPos = append(digitPos, i)
		}
	}
	out := []rune(picture)
	for idx, ppos := range digitPos {
		if idx < len(digitSeq) {
			out[ppos] = rune(digitSeq[idx])
		}
	}
	// suppression for integer part
	suppressing := true
	for i := 0; i < intCount; i++ {
		ppos := digitPos[i]
		picChar := rune(picture[ppos])
		digitChar := rune(digitSeq[i])
		if suppressing {
			if picChar == 'Z' && digitChar == '0' {
				out[ppos] = ' '
			} else {
				// keep digitChar already placed
				suppressing = false
			}
		}
	}
	// commas
	for i, ch := range picture {
		if ch == ',' {
			allSuppressed := true
			for j := 0; j < intCount; j++ {
				ppos := digitPos[j]
				if ppos < i {
					if out[ppos] != ' ' {
						allSuppressed = false
						break
					}
				}
			}
			if allSuppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	return string(out)
}

// COBOL paragraphs

func MainPara() {
	openAmtFile()
	ReadPara()
	for !InputDone {
		ProcessPara()
	}
	closeAmtFile()
	SummaryPara()
}

func openAmtFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	amtFile = f
	amtScanner = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	amtScanner.Buffer(buf, 1024*1024)
}

func closeAmtFile() {
	if amtFile != nil {
		amtFile.Close()
	}
}

func ReadPara() {
	if amtScanner.Scan() {
		line := amtScanner.Text()
		if len(line) < 11 {
			line += strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		AmtRecData.ArAcct = line[0:4]
		amtField := line[4:11]
		AmtRecData.ArAmt = parseAmtField(amtField)
		WsEofFlag = "N"
		InputDone = false
	} else {
		if err := amtScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
		InputDone = true
	}
}

func ProcessPara() {
	WsBigTotal = addWithWrap(WsBigTotal, AmtRecData.ArAmt, picBig)
	WsWrapTotal = moveWithWrap(WsBigTotal, picWrap)

	tentativeSafe := AmtRecData.ArAmt.Add(WsSafeTotal).Truncate(int32(picSafe.Scale))
	if isOverflow(tentativeSafe, picSafe) {
		OverflowPara()
	} else {
		WsSafeTotal = tentativeSafe
	}

	WsCount = (WsCount + 1) % 100

	halfDiv := AmtRecData.ArAmt.Div(decimal.NewFromInt(2))
	WsHalf = halfDiv.Truncate(int32(picHalfInfo.Scale))
	if isOverflow(WsHalf, picHalfInfo) {
		WsHalf = wrapDecimal(WsHalf, picHalfInfo)
	}

	WsAmtEd = formatEdited(AmtRecData.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	fmt.Printf("%s %s %s %s %s\n", AmtRecData.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}
